package com.medicore.prescription.entity; import jakarta.persistence.*;
@Entity @Table(name="prescriptions") public class Prescription {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long userId; @Column(nullable=false) private Long orderId; @Column(nullable=false) private Long medicineId; @Column(nullable=false) private String instructions; @Column(nullable=false) private String status="PENDING"; protected Prescription(){} public Prescription(Long userId,Long orderId,Long medicineId,String instructions){this.userId=userId;this.orderId=orderId;this.medicineId=medicineId;this.instructions=instructions;} public Long getId(){return id;} public Long getUserId(){return userId;} public Long getOrderId(){return orderId;} public Long getMedicineId(){return medicineId;} public String getInstructions(){return instructions;} public String getStatus(){return status;} public void setStatus(String status){this.status=status;}}
